                        for (int32_t q_y = 0; q_y < ((3 - q_x) + 1); q_y += 1) {
                            for (int32_t q_z = 0; q_z < (((3 - q_x) - q_y) + 1); q_z += 1) {
                                double g = 0.0;
                                int32_t e_i = 0;
                                for (int32_t e_tx = 0; e_tx < ((ax + bx) + 1); e_tx += 1) {
                                    for (int32_t e_ty = 0; e_ty < ((ay + by) + 1); e_ty += 1) {
                                        for (int32_t e_tz = 0; e_tz < ((az + bz) + 1); e_tz += 1) {
                                            g = (g + (Er[e_i] * R[(((((((e_tx + q_x) + ((e_ty + q_y) + (e_tz + q_z))) * (((e_tx + q_x) + ((e_ty + q_y) + (e_tz + q_z))) + 1)) * (((e_tx + q_x) + ((e_ty + q_y) + (e_tz + q_z))) + 2)) / 6) + ((((e_ty + q_y) + (e_tz + q_z)) * (((e_ty + q_y) + (e_tz + q_z)) + 1)) / 2)) + (e_tz + q_z))]));
                                            e_i = (e_i + 1);
                                        }
                                    }
                                }
                                G[((((((q_x + (q_y + q_z)) * ((q_x + (q_y + q_z)) + 1)) * ((q_x + (q_y + q_z)) + 2)) / 6) + (((q_y + q_z) * ((q_y + q_z) + 1)) / 2)) + q_z)] = g;
                            }
                        }
                    }
                    // per column (c, d): out += (+-) w SUM_q E^{cd}_q(-X) G[q], rolled over the
                    // ket tables, in place
                    for (int32_t c_u = 0; c_u < 2; c_u += 1) {
                        for (int32_t c_w = 0; c_w < (c_u + 1); c_w += 1) {
                            int32_t cx = (1 - c_u);
                            int32_t cy = (c_u - c_w);
                            int32_t cz = c_w;
                            for (int32_t d_u = 0; d_u < 3; d_u += 1) {
                                for (int32_t d_w = 0; d_w < (d_u + 1); d_w += 1) {
                                    int32_t dx = (2 - d_u);
                                    int32_t dy = (d_u - d_w);
                                    int32_t dz = d_w;
                                    int32_t f_bx = (((cx * 3) + dx) * 4);
                                    int32_t f_by = (((cy * 3) + dy) * 4);
                                    int32_t f_bz = (((cz * 3) + dz) * 4);
                                    double v = 0.0;
                                    for (int32_t f_tx = 0; f_tx < ((cx + dx) + 1); f_tx += 1) {
                                        double f_sy = 0.0;
                                        for (int32_t f_ty = 0; f_ty < ((cy + dy) + 1); f_ty += 1) {
                                            double f_sz = 0.0;
                                            for (int32_t f_tz = 0; f_tz < ((cz + dz) + 1); f_tz += 1) {
                                                f_sz = (f_sz + (Ekz[(f_bz + f_tz)] * G[((((((f_tx + (f_ty + f_tz)) * ((f_tx + (f_ty + f_tz)) + 1)) * ((f_tx + (f_ty + f_tz)) + 2)) / 6) + (((f_ty + f_tz) * ((f_ty + f_tz) + 1)) / 2)) + f_tz)]));
                                            }
                                            f_sy = (f_sy + (Eky[(f_by + f_ty)] * f_sz));
                                        }
                                        v = (v + (Ekx[(f_bx + f_tx)] * f_sy));
                                    }
                                    if (first) {
                                        eri[(pr * n_pp + pidx[((oc + (((c_u * (c_u + 1)) / 2) + c_w)) * n_ao + (od + (((d_u * (d_u + 1)) / 2) + d_w)))])] = (0.0 - (w * v));
                                    } else {
                                        eri[(pr * n_pp + pidx[((oc + (((c_u * (c_u + 1)) / 2) + c_w)) * n_ao + (od + (((d_u * (d_u + 1)) / 2) + d_w)))])] = (eri[(pr * n_pp + pidx[((oc + (((c_u * (c_u + 1)) / 2) + c_w)) * n_ao + (od + (((d_u * (d_u + 1)) / 2) + d_w)))])] - (w * v));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        // the bra-ket mirror of every owned element
        for (int32_t mr = r0; mr < (r0 + 1); mr += 1) {
            int32_t ra = (mr / 3);
            int32_t rb = (mr - (ra * 3));
            int32_t pr = pidx[((oa + ra) * n_ao + (ob + rb))];
            for (int32_t ci = 0; ci < 3; ci += 1) {
                for (int32_t di = 0; di < 6; di += 1) {
                    eri[(pidx[((oc + ci) * n_ao + (od + di))] * n_pp + pr)] = eri[(pr * n_pp + pidx[((oc + ci) * n_ao + (od + di))])];
                }
            }
        }
    }
}
